//! Oracle tests for `oh-replay` — the byte-exact pins from
//! `.agents/plans/001-rust-port/mapping/oracle-vectors.md` (generated by the
//! C++ build at commit `1e2cba71`, `g++ -std=c++20 -O0` on this machine).
//!
//! Fixture: version=5, player_name="tester", seed=12345,
//! pack_id="ohvrvanilla", level_id="cube_1_apeirogon", first_play=true,
//! difficulty_mult=1.6f, played_score=3600.0; inputs (l,r,s,f) =
//! 0000, 0100, 1010, 0000, 0100, 1001.
//!
//! These tests assert the exact HEX / CZHEX / PHEX byte strings — they are
//! NOT self-consistent round-trips, so any encoding/endianness/field-order
//! slip fails here.

use oh_replay::{
    compress_replay_file, decompress_replay_file, CompressedReplayFile, InputBits, Packet,
    ReplayData, ReplayFile, ReplayPlayer,
};

/// Oracle `HEX=` (84-byte file-form serialization of the fixture).
const HEX: &str = "0500000006000000746573746572393000000000000006000000000000000002050002090b0000006f68767276616e696c6c6110000000637562655f315f61706569726f676f6e01cdcccc3f000000000020ac40";

/// Oracle `CZHEX=` (76-byte zlib level-9 compression of the file form).
const CZHEX: &str = "78da636560606003e292d4e292d4224b03063060638002265606264e6e20233fa3aca82c312f3327275100c84d2e4d4a8d378c4f2c48cd2cca4fcfcf633c7be68c3d5887c21a070042d611e8";

/// Oracle `PHEX=` (92-byte packet form: u64-BE length prefix + file bytes).
const PHEX: &str = "00000000000000540500000006000000746573746572393000000000000006000000000000000002050002090b0000006f68767276616e696c6c6110000000637562655f315f61706569726f676f6e01cdcccc3f000000000020ac40";

fn fixture() -> ReplayFile {
    let mut rf = ReplayFile {
        version: 5,
        player_name: "tester".to_string(),
        seed: 12345,
        pack_id: "ohvrvanilla".to_string(),
        level_id: "cube_1_apeirogon".to_string(),
        first_play: true,
        difficulty_mult: 1.6f32,
        played_score: 3600.0,
        ..ReplayFile::default()
    };
    // inputs (l, r, s, f): 0000, 0100, 1010, 0000, 0100, 1001
    rf.data.record_input(false, false, false, false);
    rf.data.record_input(false, true, false, false);
    rf.data.record_input(true, false, true, false);
    rf.data.record_input(false, false, false, false);
    rf.data.record_input(false, true, false, false);
    rf.data.record_input(true, false, false, true);
    rf
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("oracle hex is valid"))
        .collect()
}

// ---------------------------------------------------------------------------
// Oracle pins
// ---------------------------------------------------------------------------

/// `replay_file` → bytes must equal the oracle `HEX` (84 bytes, file form:
/// little-endian fields, u32-LE-prefixed strings, one byte per input).
#[test]
fn oracle_serialize_file_equals_hex() {
    let rf = fixture();
    let mut buf = vec![0u8; 2097152]; // heap: a 2 MiB stack array overflows test threads
    let sr = rf.serialize(buf.as_mut_slice());
    assert!(sr.is_success(), "serialize must succeed");
    assert_eq!(sr.written_bytes(), 84, "serialized_bytes=84 (oracle)");
    assert_eq!(
        &hex(&buf[..sr.written_bytes()]),
        HEX,
        "file-form serialization must byte-match the C++ oracle HEX"
    );
}

/// The oracle `HEX` must deserialize back to the fixture struct.
#[test]
fn oracle_deserialize_file_equals_fixture() {
    let rf = fixture();
    let bytes = unhex(HEX);
    let mut out = ReplayFile::default();
    let dr = out.deserialize(&bytes);
    assert!(dr.is_success(), "deserialize must succeed");
    assert_eq!(dr.read_bytes(), 84);
    assert_eq!(out, rf, "HEX must decode to the fixture");
}

/// `compress_replay_file` output must equal the oracle `CZHEX` (byte-exact
/// zlib level-9 stream — requires the same deflate implementation as the
/// C++ build, see DECISIONS.md D-006).
#[test]
fn oracle_compress_equals_czhex() {
    let crf = compress_replay_file(&fixture()).expect("compress_replay_file must succeed");
    assert_eq!(
        hex(&crf.data),
        CZHEX,
        "compressed bytes must byte-match the C++ oracle CZHEX"
    );
}

/// The oracle `CZHEX` blob must decompress to the fixture.
#[test]
fn oracle_decompress_czhex_equals_fixture() {
    let crf = CompressedReplayFile { data: unhex(CZHEX) };
    let rf = decompress_replay_file(&crf).expect("decompress_replay_file must succeed");
    assert_eq!(rf, fixture(), "CZHEX must decompress to the fixture");
}

/// `serialize_to_packet` must equal the oracle `PHEX` (92 bytes: u64
/// **big-endian** length prefix `0000000000000054` = 84, then the file
/// bytes — the SFML packet form).
#[test]
fn oracle_serialize_to_packet_equals_phex() {
    let mut p = Packet::new();
    assert!(fixture().serialize_to_packet(&mut p));
    assert_eq!(p.size(), 92, "packet_bytes=92 (oracle)");
    assert_eq!(
        hex(p.data()),
        PHEX,
        "packet form must byte-match the C++ oracle PHEX (BE u64 prefix + LE file bytes)"
    );
}

/// The packet form must round-trip through `deserialize_from_packet`.
#[test]
fn oracle_deserialize_from_packet() {
    let rf = fixture();
    let mut p = Packet::new();
    assert!(rf.serialize_to_packet(&mut p));
    let mut out = ReplayFile::default();
    assert!(out.deserialize_from_packet(&mut p));
    assert_eq!(out, rf);
}

/// Oracle `PLAYED_SECONDS=60` — `played_score / 60.0`.
#[test]
fn oracle_played_seconds() {
    assert_eq!(fixture().played_seconds(), 60.0);
}

/// Emits the fixture's golden bytes so the orchestrator can diff them
/// against a fresh C++ oracle run (02-replay.md verification step). Run
/// with: `cargo test -p oh-replay --test oracle -- --nocapture emit_fixture`
#[test]
fn emit_fixture_hex_for_oracle_diff() {
    let rf = fixture();
    let mut buf = vec![0u8; 2097152]; // heap: a 2 MiB stack array overflows test threads
    let sr = rf.serialize(buf.as_mut_slice());
    println!("serialized_bytes={}", sr.written_bytes());
    println!("HEX={}", hex(&buf[..sr.written_bytes()]));
    println!("PLAYED_SECONDS={:.*}", 9, rf.played_seconds());
    if let Some(crf) = compress_replay_file(&rf) {
        println!("compressed_bytes={}", crf.data.len());
        println!("CZHEX={}", hex(&crf.data));
        match decompress_replay_file(&crf) {
            Some(back) => println!("roundtrip_equal={}", u8::from(back == rf)),
            None => println!("roundtrip_equal=0"),
        }
    } else {
        println!("compression_failed");
    }
    let mut p = Packet::new();
    assert!(rf.serialize_to_packet(&mut p));
    println!("packet_bytes={}", p.size());
    println!("PHEX={}", hex(p.data()));
}

// ---------------------------------------------------------------------------
// Unit tests (behavior of the ported API, not oracle bytes)
// ---------------------------------------------------------------------------

#[test]
fn input_bits_encode_bits_0_to_3_in_l_r_s_f_order() {
    // C++: record_input(true,false,true,false) -> 0b0101 = 5 (oracle note).
    assert_eq!(InputBits::new(true, false, true, false).to_u8(), 0x05);
    assert_eq!(InputBits::new(false, true, false, false).to_u8(), 0x02);
    assert_eq!(InputBits::new(true, false, false, true).to_u8(), 0x09);
    assert_eq!(InputBits::new(false, false, false, false).to_u8(), 0x00);

    // from_byte keeps only the low 4 bits (std::bitset<4> semantics).
    assert_eq!(
        InputBits::from_byte(0xFF),
        InputBits::new(true, true, true, true)
    );
    assert_eq!(InputBits::from_byte(0x09).to_u8(), 0x09);

    // Accessors agree with the bit positions.
    let ib = InputBits::new(true, false, true, false);
    assert!(ib.left() && ib.swap() && !ib.right() && !ib.focus());
}

#[test]
fn replay_data_serialize_deserialize_roundtrip() {
    let mut rd = ReplayData::default();
    rd.record_input(true, false, true, false);
    rd.record_input(false, true, false, true);
    rd.record_input(false, false, false, false);

    let mut buf = [0u8; 64];
    let sr = rd.serialize(&mut buf);
    assert!(sr.is_success());
    // u64 count (8) + 3 bytes
    assert_eq!(sr.written_bytes(), 11);
    assert_eq!(&hex(&buf[..sr.written_bytes()]), "0300000000000000050a00");

    let mut back = ReplayData::default();
    let dr = back.deserialize(&buf[..sr.written_bytes()]);
    assert!(dr.is_success());
    assert_eq!(dr.read_bytes(), 11);
    assert_eq!(back, rd);
}

#[test]
fn replay_data_with_size_overloads_match_slice_semantics() {
    let mut rd = ReplayData::default();
    rd.record_input(true, true, true, true);

    let mut buf = [0u8; 16];
    let full = rd.serialize(&mut buf);
    let sized = rd.serialize_with_size(&mut buf, 9); // 8 count + 1 byte
    assert_eq!(full, sized);
    assert_eq!(sized.written_bytes(), 9);

    let mut back = ReplayData::default();
    let dr = back.deserialize_with_size(&buf[..9], 9);
    assert!(dr.is_success());
    assert_eq!(back, rd);
}

#[test]
fn replay_data_serialize_into_tiny_buffer_fails_with_partial_write() {
    // C++ semantics: partial write => failure, written_bytes counts the
    // bytes that actually fit (u64 count = 8 bytes, then 1 of 2 input bytes).
    let mut rd = ReplayData::default();
    rd.record_input(true, false, false, false);
    rd.record_input(false, true, false, false);

    let mut buf = [0u8; 9];
    let sr = rd.serialize(&mut buf);
    assert!(!sr.is_success());
    assert_eq!(sr.written_bytes(), 9);
}

#[test]
fn replay_data_deserialize_hostile_input_count_fails_cleanly() {
    // n_inputs claims 2^64-1 inputs; the C++ build would attempt a ~16 EiB
    // resize (terminate). The port must fail cleanly with success = false.
    let mut rd = ReplayData::default();
    let bytes = vec![0xFFu8; 8]; // u64::MAX little-endian
    let dr = rd.deserialize(&bytes);
    assert!(!dr.is_success());
    assert_eq!(dr.read_bytes(), 8);
}

#[test]
fn replay_file_deserialize_hostile_string_length_fails_cleanly() {
    // version=1, player_name length = 0xFFFFFFFF (u32::MAX LE), 4 bytes.
    let mut rf = ReplayFile::default();
    let bytes = [0x01u8, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0xFF, 0xFF];
    let dr = rf.deserialize(&bytes);
    assert!(!dr.is_success());
}

#[test]
fn replay_player_walks_inputs_and_exhausts() {
    let mut rd = ReplayData::default();
    rd.record_input(true, false, false, false); // 0x01
    rd.record_input(false, true, false, false); // 0x02
    let player = &mut ReplayPlayer::new(&rd);

    assert!(!player.done());
    assert_eq!(player.get_current_and_move_forward().to_u8(), 0x01);
    assert!(!player.done());
    assert_eq!(player.get_current_and_move_forward().to_u8(), 0x02);
    assert!(player.done());
    // Exhausted: the C++ `return {};` — the default (all-clear) bitset.
    assert_eq!(player.get_current_and_move_forward(), InputBits::none());

    player.reset();
    assert!(!player.done());
    assert_eq!(player.get_current_and_move_forward().to_u8(), 0x01);
}

#[test]
fn replay_file_serialize_deserialize_roundtrip() {
    let rf = fixture();
    let mut buf = vec![0u8; 2097152]; // heap: a 2 MiB stack array overflows test threads
    let sr = rf.serialize(buf.as_mut_slice());
    assert!(sr.is_success());

    let mut back = ReplayFile::default();
    let dr = back.deserialize(&buf[..sr.written_bytes()]);
    assert!(dr.is_success());
    assert_eq!(back, rf);
}

#[test]
fn replay_file_file_roundtrip() {
    let dir = std::env::temp_dir().join(format!("oh-replay-test-{}", std::process::id()));
    std::fs::create_dir_all(&dir).expect("temp dir");
    let path = dir.join("fixture.ohr");

    let rf = fixture();
    assert!(rf.serialize_to_file(&path));

    let mut back = ReplayFile::default();
    assert!(back.deserialize_from_file(&path));
    assert_eq!(back, rf);

    // Missing path: C++ prints "Couldn't open replay path '...'"; false.
    assert!(!ReplayFile::default().deserialize_from_file(dir.join("missing.ohr")));

    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn compressed_replay_file_file_roundtrip() {
    let dir = std::env::temp_dir().join(format!("oh-replay-cz-test-{}", std::process::id()));
    std::fs::create_dir_all(&dir).expect("temp dir");
    let path = dir.join("fixture.czh");

    let crf = compress_replay_file(&fixture()).expect("compress");
    assert!(crf.serialize_to_file(&path));

    let mut back = CompressedReplayFile::default();
    assert!(back.deserialize_from_file(&path));
    assert_eq!(back, crf);

    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn compressed_replay_file_packet_roundtrip() {
    let crf = compress_replay_file(&fixture()).expect("compress");
    let mut p = Packet::new();
    assert!(crf.serialize_to_packet(&mut p));

    let mut back = CompressedReplayFile::default();
    assert!(back.deserialize_from_packet(&mut p));
    assert_eq!(back, crf);
}

#[test]
fn compressed_replay_file_packet_hostile_length_fails() {
    // u64-BE length = 0xFFFFFFFFFFFFFFFF (18 EiB) — C++ would resize to it
    // (terminate); the port must fail against the (empty) packet.
    let mut p = Packet::new();
    p.write_u64(u64::MAX);
    let mut crf = CompressedReplayFile::default();
    assert!(!crf.deserialize_from_packet(&mut p));
    assert!(crf.data.is_empty());
}

#[test]
fn create_filename_matches_cpp_format() {
    // C++: `{version}_{%Y%m%d_%H%M%S UTC}_{player_name}_{level_id}_
    //      {difficulty mult}x_{played seconds}s.ohr`, floats formatted like
    // `std::ostream <<` (1.6f -> "1.6", 60.0 -> "60" — pinned by issue-001's
    // concat oracle tests). The embedded timestamp is wall-clock, so check
    // the name against the format built from the second before and after
    // the call (either must match exactly; this pins the full shape).
    let rf = fixture();
    let ts_before = oh_math::hg::timestamp::now_timestamp();
    let name = rf.create_filename();
    let ts_after = oh_math::hg::timestamp::now_timestamp();

    fn build(ts: u64) -> String {
        let tp = oh_math::hg::timestamp::to_timepoint(ts);
        let tp_str = oh_math::hg::timestamp::format_timepoint(tp, "%Y%m%d_%H%M%S");
        oh_math::hg::concat::concat(&[
            oh_math::hg::concat::ConcatPart::U32(5),
            oh_math::hg::concat::ConcatPart::Str("_"),
            oh_math::hg::concat::ConcatPart::Str(&tp_str),
            oh_math::hg::concat::ConcatPart::Str("_"),
            oh_math::hg::concat::ConcatPart::Str("tester"),
            oh_math::hg::concat::ConcatPart::Str("_"),
            oh_math::hg::concat::ConcatPart::Str("cube_1_apeirogon"),
            oh_math::hg::concat::ConcatPart::Str("_"),
            oh_math::hg::concat::ConcatPart::F32(1.6f32),
            oh_math::hg::concat::ConcatPart::Str("x_"),
            oh_math::hg::concat::ConcatPart::F64(60.0),
            oh_math::hg::concat::ConcatPart::Str("s.ohr"),
        ])
    }
    assert!(
        name == build(ts_before) || name == build(ts_after),
        "create_filename {name:?} must be the C++ format at the current second"
    );

    // Shape sanity: `5_YYYYMMDD_HHMMSS_tester_cube_1_apeirogon_1.6x_60s.ohr`.
    assert!(name.starts_with("5_"));
    assert!(name.ends_with("_tester_cube_1_apeirogon_1.6x_60s.ohr"));
    let ts_part = name
        .strip_prefix("5_")
        .expect("prefix")
        .split_once("_tester_")
        .expect("timestamp followed by player name")
        .0;
    assert_eq!(ts_part.len(), 15, "YYYYMMDD_HHMMSS");
    let (date, time) = ts_part.split_once('_').expect("date_time");
    assert_eq!(date.len(), 8);
    assert_eq!(time.len(), 6);
    assert!(date.bytes().all(|b| b.is_ascii_digit()));
    assert!(time.bytes().all(|b| b.is_ascii_digit()));
}

// ---------------------------------------------------------------------------
// sf::Packet encoding table (oracle-vectors.md "SFML Packet encoding rules")
// ---------------------------------------------------------------------------

#[test]
fn packet_integers_are_big_endian() {
    let mut p = Packet::new();
    p.write_u16(0x1234);
    p.write_u32(0x12345678);
    p.write_u64(0x0102030405060708);
    p.write_i16(-2); // 0xFFFE bit pattern, big-endian
    p.write_i32(-0x1234_5678);
    p.write_i64(-0x0102_0304_0506_0708);
    assert_eq!(
        p.data(),
        &[
            0x12, 0x34, 0x12, 0x34, 0x56, 0x78, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,
            0xFF, 0xFE, 0xED, 0xCB, 0xA9, 0x88, 0xFE, 0xFD, 0xFC, 0xFB, 0xFA, 0xF9, 0xF8, 0xF8,
        ]
    );
}

#[test]
fn packet_floats_are_raw_little_endian() {
    // The trap: file form is LE and so is the packet float form (raw
    // memcpy, NOT byte-swapped).
    let mut p = Packet::new();
    p.write_f32(1.6f32);
    p.write_f64(3600.0f64);
    assert_eq!(
        p.data(),
        &[0xCD, 0xCC, 0xCC, 0x3F, 0x00, 0x00, 0x00, 0x00, 0x00, 0x20, 0xAC, 0x40]
    );
    assert_eq!(p.read_f32(), Some(1.6f32));
    assert_eq!(p.read_f64(), Some(3600.0f64));
}

#[test]
fn packet_string_is_u32_be_length_plus_raw_bytes() {
    let mut p = Packet::new();
    p.write_str("tester");
    assert_eq!(
        p.data(),
        &[0x00, 0x00, 0x00, 0x06, b't', b'e', b's', b't', b'e', b'r']
    );
    assert_eq!(p.read_str(), Some("tester".to_string()));

    // Empty string: length 0, no bytes.
    let mut p2 = Packet::new();
    p2.write_str("");
    assert_eq!(p2.data(), &[0x00, 0x00, 0x00, 0x00]);
    assert_eq!(p2.read_str(), Some(String::new()));
}

#[test]
fn packet_bool_and_u8_are_single_raw_bytes() {
    let mut p = Packet::new();
    p.write_bool(true);
    p.write_bool(false);
    p.write_u8(0xAB);
    p.write_i8(-0x5B); // 0xA5 two's complement
    assert_eq!(p.data(), &[1, 0, 0xAB, 0xA5]);
    assert_eq!(p.read_bool(), Some(true));
    assert_eq!(p.read_bool(), Some(false));
    assert_eq!(p.read_u8(), Some(0xAB));
    assert_eq!(p.read_i8(), Some(-0x5B));
}

#[test]
fn packet_append_is_raw_bytes() {
    let mut p = Packet::new();
    p.append(&[0xDE, 0xAD, 0xBE, 0xEF]);
    assert_eq!(p.data(), &[0xDE, 0xAD, 0xBE, 0xEF]);
    assert_eq!(p.size(), 4);
}

#[test]
fn packet_reads_fail_with_none_and_do_not_advance_past_failure() {
    let mut p = Packet::new();
    p.write_u16(0x1234);
    // u32 read with only 2 bytes present: None, read position unchanged.
    assert_eq!(p.read_u32(), None);
    // The u16 still reads (position never advanced).
    assert_eq!(p.read_u16(), Some(0x1234));
    assert_eq!(p.read_u16(), None);

    // read_str: length claims 10 bytes but only 4 are present.
    let mut p2 = Packet::new();
    p2.write_u32(10);
    p2.append(b"abcd");
    assert_eq!(p2.read_str(), None);
}

#[test]
fn packet_reset_clears_everything() {
    let mut p = Packet::new();
    p.write_u64(42);
    p.write_str("hi");
    p.reset();
    assert_eq!(p.size(), 0);
    assert_eq!(p.available(), 0);
    assert_eq!(p.read_u64(), None);
}
